        V('Would you enhance a future child if the technology existed?', 'Вы бы улучшили будущего ребёнка, если бы такая технология существовала?', 'Мұндай технология болса, болашақ баланы жетілдірер ме едіңіз?'),
        V('What line do you think should never be crossed in human enhancement?', 'Какую грань, по-вашему, никогда не следует пересекать в улучшении человека?', 'Сіздің ойыңызша, адамды жетілдіруде қашан да аттамауы керек шек қандай?'),
    ],
];

$lessons[] = ['level' => 'intermediate', 'topic' => 'Reparations and Historical Justice', 'background_key' => 'minimal-dark',
    'warmup' => V("Let's talk about historical justice. Should nations or institutions pay reparations for historical wrongs?", 'Давайте поговорим об исторической справедливости. Должны ли нации или институты выплачивать репарации за исторические несправедливости?', 'Тарихи әділеттілік туралы сөйлесейік. Ұлттар немесе институттар тарихи әділетсіздіктер үшін өтемақы төлеуі керек пе?'),
    'vocab' => [V('reparations', 'репарации', 'өтемақы'), V('historical injustice', 'историческая несправедливость', 'тарихи әділетсіздік'), V('accountability', 'подотчётность', 'жауапкершілік'), V('collective guilt', 'коллективная вина', 'ұжымдық кінә'), V('generational impact', 'влияние на поколения', 'ұрпаққа әсер'), V('acknowledgment', 'признание', 'мойындау'), V('restitution', 'возмещение', 'өтемақы (заттай)'), V('systemic', 'системный', 'жүйелік'), V('reconciliation', 'примирение', 'татуласу'), V('moral debt', 'моральный долг', 'моральдық борыш')],
    'questions' => [
        V('Do you think reparations for historical wrongs are fair?', 'Как вы думаете, репарации за исторические несправедливости справедливы?', 'Тарихи әділетсіздіктер үшін өтемақы әділ деп ойлайсыз ба?'),
        V('Should living people be responsible for wrongs committed by past generations?', 'Должны ли живые люди нести ответственность за несправедливости, совершённые прошлыми поколениями?', 'Тірі адамдар өткен ұрпақ жасаған әділетсіздіктерге жауапты болуы керек пе?'),
        V('Do you think acknowledgment alone is enough, without financial compensation?', 'Как вы думаете, одного признания достаточно, без финансовой компенсации?', 'Тек мойындау қаржылай өтемақысыз жеткілікті ме деп ойлайсыз ба?'),
        V('Does your country have a history that might require reparations?', 'В истории вашей страны есть события, которые могли бы потребовать репараций?', 'Еліңіздің тарихында өтемақыны қажет ететін оқиға бар ма?'),
        V('Do you think reparations could actually help repair historical harm?', 'Как вы думаете, репарации действительно могут помочь исправить исторический вред?', 'Өтемақы тарихи зиянды шынымен түзетуге көмектесе алады деп ойлайсыз ба?'),
        V('Should reparations be paid to individuals or to communities as a whole?', 'Должны ли репарации выплачиваться отдельным людям или сообществам в целом?', 'Өтемақы жеке адамдарға немесе бүтіндей қауымдастықтарға төленуі керек пе?'),
        V('Do you think systemic inequality today is connected to historical injustice?', 'Как вы думаете, сегодняшнее системное неравенство связано с исторической несправедливостью?', 'Бүгінгі жүйелік теңсіздік тарихи әділетсіздікпен байланысты деп ойлайсыз ба?'),
        V('Would reparations help with reconciliation, or create more division?', 'Помогли бы репарации примирению, или создали бы больше разногласий?', 'Өтемақы татуласуға көмектесе ме, әлде көбірек бөлінушілік тудыра ма?'),
        V('Do you think there is a "moral debt" that should be repaid?', 'Как вы думаете, есть "моральный долг", который следует вернуть?', 'Қайтарылуы керек "моральдық борыш" бар деп ойлайсыз ба?'),
        V('Should reparations come in the form of money, or other kinds of support?', 'Должны ли репарации быть в виде денег, или другой поддержки?', 'Өтемақы ақша түрінде болуы керек пе, әлде басқа қолдау түрінде ме?'),
        V('Do you think it is possible to calculate a fair amount for historical harm?', 'Как вы думаете, возможно ли рассчитать справедливую сумму за исторический вред?', 'Тарихи зиян үшін әділ соманы есептеу мүмкін бе деп ойлайсыз ба?'),
        V('Do you think public education about historical wrongs is a form of reparations?', 'Как вы думаете, общественное образование об исторических несправедливостях — это форма репараций?', 'Тарихи әділетсіздіктер туралы қоғамдық білім беру өтемақының бір түрі ме деп ойлайсыз ба?'),
        V('Would you support a policy of reparations in your own country?', 'Вы бы поддержали политику репараций в своей стране?', 'Өз еліңізде өтемақы саясатын қолдар ма едіңіз?'),
        V('Do you think reparations debates are more about money or about respect?', 'Как вы думаете, дебаты о репарациях больше про деньги или про уважение?', 'Өтемақы туралы пікірталастар ақшаға көбірек байланысты ма, әлде құрметке ме деп ойлайсыз ба?'),
        V('What would meaningful historical justice look like to you?', 'Как бы выглядела значимая историческая справедливость для вас?', 'Сіз үшін мағыналы тарихи әділеттілік қандай болар еді?'),
    ],
];

$lessons[] = ['level' => 'intermediate', 'topic' => 'The Rise of Voice Cloning Technology', 'background_key' => 'night-city',
    'warmup' => V("Let's talk about voice cloning. How do you feel about AI that can perfectly imitate someone's voice?", 'Давайте поговорим о клонировании голоса. Что вы думаете об ИИ, который может идеально имитировать чей-то голос?', 'Дауысты клондау туралы сөйлесейік. Біреудің дауысын мінсіз еліктей алатын ЖИ туралы не ойлайсыз?'),
    'vocab' => [V('voice cloning', 'клонирование голоса', 'дауысты клондау'), V('synthetic voice', 'синтетический голос', 'синтетикалық дауыс'), V('consent', 'согласие', 'келісім'), V('impersonation', 'выдача себя за другого', 'басқа адам болып көрсету'), V('fraud', 'мошенничество', 'алаяқтық'), V('authentication', 'аутентификация', 'түпнұсқалығын растау'), V('audio deepfake', 'аудио дипфейк', 'аудио дипфейк'), V('scam call', 'мошеннический звонок', 'алаяқтық қоңырауы'), V('voice actor', 'актёр озвучивания', 'дыбыстау актёрі'), V('regulation', 'регулирование', 'реттеу')],
    'questions' => [
        V('How do you feel about AI that can perfectly clone someone\'s voice?', 'Что вы думаете об ИИ, который может идеально клонировать чей-то голос?', 'Біреудің дауысын мінсіз клондай алатын ЖИ туралы не ойлайсыз?'),
        V('Have you heard of scam calls using cloned voices?', 'Вы слышали о мошеннических звонках с использованием клонированных голосов?', 'Клондалған дауыстарды пайдаланатын алаяқтық қоңыраулары туралы естідіңіз бе?'),
        V('Should companies be required to get consent before cloning a voice?', 'Должны ли компании быть обязаны получать согласие перед клонированием голоса?', 'Компаниялар дауысты клондамас бұрын келісім алуға міндетті болуы керек пе?'),
        V('Do you think this technology threatens voice actors\' jobs?', 'Как вы думаете, эта технология угрожает работе актёров озвучивания?', 'Бұл технология дыбыстау актёрлерінің жұмысына қауіп төндіреді деп ойлайсыз ба?'),
        V('Would you trust a phone call if you couldn\'t verify the voice was real?', 'Вы бы доверяли телефонному звонку, если бы не могли проверить, что голос настоящий?', 'Дауыстың шын екенін тексере алмасаңыз, телефон қоңырауына сенер ме едіңіз?'),
        V('Do you think voice authentication for banking is still safe?', 'Как вы думаете, аутентификация по голосу для банкинга всё ещё безопасна?', 'Банк ісі үшін дауыс арқылы растау әлі де қауіпсіз бе деп ойлайсыз ба?'),
        V('Should there be laws specifically about voice cloning fraud?', 'Должны ли быть законы, специально касающиеся мошенничества с клонированием голоса?', 'Дауысты клондау алаяқтығы туралы арнайы заңдар болуы керек пе?'),
        V('Do you think family members could be fooled by a cloned voice asking for help?', 'Как вы думаете, членов семьи можно обмануть клонированным голосом, просящим помощи?', 'Отбасы мүшелерін көмек сұрайтын клондалған дауыс алдай алады деп ойлайсыз ба?'),
        V('Would you want your own voice protected from being cloned?', 'Вы бы хотели, чтобы ваш собственный голос был защищён от клонирования?', 'Өз дауысыңыздың клондаудан қорғалғанын қалайсыз ба?'),
        V('Do you think there are positive uses for voice cloning technology?', 'Как вы думаете, есть ли положительные применения технологии клонирования голоса?', 'Дауысты клондау технологиясының оң қолданыстары бар деп ойлайсыз ба?'),
        V('Could voice cloning help people who have lost their ability to speak?', 'Могло бы клонирование голоса помочь людям, потерявшим способность говорить?', 'Дауысты клондау сөйлеу қабілетінен айырылған адамдарға көмектесе ала ма?'),
        V('Do you check who is calling before trusting a voice on the phone?', 'Вы проверяете, кто звонит, прежде чем доверять голосу по телефону?', 'Телефондағы дауысқа сенбес бұрын кім қоңырау шалып жатқанын тексересіз бе?'),
        V('Should movies and media be required to label AI-generated voices?', 'Должны ли фильмы и медиа быть обязаны маркировать голоса, созданные ИИ?', 'Фильмдер мен медиа ЖИ жасаған дауыстарды белгілеуге міндетті болуы керек пе?'),
        V('Do you think this technology will become common in everyday scams?', 'Как вы думаете, эта технология станет обычной в повседневном мошенничестве?', 'Бұл технология күнделікті алаяқтықта кең таралады деп ойлайсыз ба?'),
        V('What safeguard would make you feel safer about this technology?', 'Какая защита заставила бы вас чувствовать себя безопаснее по поводу этой технологии?', 'Бұл технология туралы өзіңізді қауіпсіздірек сезінуге қандай қорғаныс көмектеседі?'),
    ],
];

$lessons[] = ['level' => 'intermediate', 'topic' => 'Climate Migration', 'background_key' => 'nature',
    'warmup' => V("Let's talk about climate migration. How will rising sea levels and extreme weather change where people live?", 'Давайте поговорим о климатической миграции. Как повышение уровня моря и экстремальная погода изменят места проживания людей?', 'Климаттық көші-қон туралы сөйлесейік. Теңіз деңгейінің көтерілуі мен экстремалды ауа райы адамдардың тұратын жерін қалай өзгертеді?'),
    'vocab' => [V('climate migration', 'климатическая миграция', 'климаттық көші-қон'), V('displacement', 'перемещение', 'орын ауыстыру'), V('sea level rise', 'повышение уровня моря', 'теңіз деңгейінің көтерілуі'), V('climate refugee', 'климатический беженец', 'климаттық босқын'), V('habitable land', 'пригодная для жизни земля', 'тұруға жарамды жер'), V('resettlement', 'переселение', 'қайта қоныстандыру'), V('resource scarcity', 'дефицит ресурсов', 'ресурс тапшылығы'), V('international law', 'международное право', 'халықаралық құқық'), V('adaptation', 'адаптация', 'бейімделу'), V('vulnerable region', 'уязвимый регион', 'осал аймақ')],
    'questions' => [
        V('Do you think climate migration will become a major global issue?', 'Как вы думаете, климатическая миграция станет крупной глобальной проблемой?', 'Климаттық көші-қон үлкен жаһандық мәселеге айналады деп ойлайсыз ба?'),
        V('Should countries be legally required to accept climate refugees?', 'Должны ли страны быть юридически обязаны принимать климатических беженцев?', 'Елдер климаттық босқындарды заңды түрде қабылдауға міндетті болуы керек пе?'),
        V('Do you think your own region could become uninhabitable in the future?', 'Как вы думаете, ваш собственный регион может стать непригодным для жизни в будущем?', 'Өз аймағыңыз болашақта тұруға жарамсыз болуы мүмкін деп ойлайсыз ба?'),
        V('Should wealthy countries help fund resettlement for vulnerable regions?', 'Должны ли богатые страны помогать финансировать переселение уязвимых регионов?', 'Бай елдер осал аймақтардың қайта қоныстандырылуын қаржыландыруға көмектесуі керек пе?'),
        V('Do you think there is currently enough international law to handle this issue?', 'Как вы думаете, в настоящее время достаточно международного права для решения этой проблемы?', 'Қазіргі уақытта бұл мәселені шешуге жеткілікті халықаралық құқық бар деп ойлайсыз ба?'),
        V('Do you think climate migration will cause conflict over resources?', 'Как вы думаете, климатическая миграция вызовет конфликты из-за ресурсов?', 'Климаттық көші-қон ресурстар үшін қақтығыс тудырады деп ойлайсыз ба?'),
        V('Would you personally move if your region became affected by climate change?', 'Вы бы лично переехали, если бы ваш регион пострадал от изменения климата?', 'Аймағыңыз климаттың өзгеруінен зардап шексе, жеке өзіңіз көшер ме едіңіз?'),
        V('Do you think cities are prepared for an influx of climate migrants?', 'Как вы думаете, города готовы к притоку климатических мигрантов?', 'Қалалар климаттық мигранттардың ағынына дайын деп ойлайсыз ба?'),
        V('Should climate refugees have the same legal status as other refugees?', 'Должны ли климатические беженцы иметь тот же юридический статус, что и другие беженцы?', 'Климаттық босқындардың басқа босқындармен бірдей заңды мәртебесі болуы керек пе?'),
        V('Do you think adaptation efforts can prevent large-scale climate migration?', 'Как вы думаете, усилия по адаптации могут предотвратить масштабную климатическую миграцию?', 'Бейімделу күш-жігері үлкен ауқымды климаттық көші-қонды болдырмай алады деп ойлайсыз ба?'),
        V('Do you think coastal cities will need to be abandoned eventually?', 'Как вы думаете, прибрежные города в конечном итоге придётся оставить?', 'Жағалаудағы қалаларды ақыр соңында тастап кетуге тура келеді деп ойлайсыз ба?'),
        V('Should governments plan now for future climate migration?', 'Должны ли правительства планировать сейчас на случай будущей климатической миграции?', 'Үкіметтер қазір болашақ климаттық көші-қонға жоспарлауы керек пе?'),
        V('Do you think climate migration will mostly happen within countries or between them?', 'Как вы думаете, климатическая миграция будет происходить в основном внутри стран или между ними?', 'Климаттық көші-қон негізінен елдер ішінде болады ма, әлде олардың арасында ма деп ойлайсыз ба?'),
        V('Do you think public awareness of climate migration is high enough?', 'Как вы думаете, общественная осведомлённость о климатической миграции достаточно высока?', 'Климаттық көші-қон туралы қоғамдық хабардарлық жеткілікті жоғары деп ойлайсыз ба?'),
        V('What responsibility do wealthy, high-emission countries have toward climate migrants?', 'Какую ответственность несут богатые страны с высоким уровнем выбросов перед климатическими мигрантами?', 'Бай, шығарынды деңгейі жоғары елдердің климаттық мигранттар алдында қандай жауапкершілігі бар?'),
    ],
];

$lessons[] = ['level' => 'intermediate', 'topic' => 'The Sociology of Online Communities', 'background_key' => 'night-city',
