    'vocab' => [V('urban planning', 'городское планирование', 'қала жоспарлау'), V('remote work', 'удалённая работа', 'қашықтан жұмыс'), V('mixed-use development', 'многофункциональная застройка', 'аралас пайдалану дамуы'), V('public space', 'общественное пространство', 'қоғамдық кеңістік'), V('resilience', 'устойчивость', 'төзімділік'), V('density', 'плотность', 'тығыздық'), V('ventilation', 'вентиляция', 'желдету'), V('walkability', 'пешеходная доступность', 'жаяу жүруге ыңғайлылық'), V('office vacancy', 'пустующие офисы', 'бос кеңселер'), V('15-minute city', '15-минутный город', '15 минуттық қала')],
    'questions' => [
        V('Do you think cities are being redesigned because of remote work?', 'Как вы думаете, города перепроектируются из-за удалённой работы?', 'Қалалар қашықтан жұмыс себебінен қайта жобалануда деп ойлайсыз ба?'),
        V('Do you think office buildings will need new uses in the future?', 'Как вы думаете, офисным зданиям понадобится новое применение в будущем?', 'Кеңсе ғимараттарына болашақта жаңа қолданыс керек болады деп ойлайсыз ба?'),
        V('Would you want to live in a "15-minute city" where everything is within walking distance?', 'Вы бы хотели жить в "15-минутном городе", где всё в шаговой доступности?', 'Барлығы жаяу қашықтықта болатын "15 минуттық қалада" тұрғыңыз келе ме?'),
        V('Do you think public spaces became more important after recent global events?', 'Как вы думаете, общественные пространства стали важнее после недавних мировых событий?', 'Соңғы жаһандық оқиғалардан кейін қоғамдық кеңістіктер маңыздырақ болды деп ойлайсыз ба?'),
        V('Should cities prioritize walkability over car infrastructure?', 'Должны ли города отдавать приоритет пешеходной доступности над автомобильной инфраструктурой?', 'Қалалар автокөлік инфрақұрылымынан гөрі жаяу жүруге ыңғайлылыққа басымдық беруі керек пе?'),
        V('Do you think dense cities are safer or riskier for public health?', 'Как вы думаете, плотные города безопаснее или рискованнее для общественного здоровья?', 'Тығыз қалалар қоғамдық денсаулық үшін қауіпсіз бе, әлде тәуекелді ме деп ойлайсыз ба?'),
        V('Would you support converting empty offices into housing?', 'Вы бы поддержали превращение пустых офисов в жильё?', 'Бос кеңселерді тұрғын үйге айналдыруды қолдар ма едіңіз?'),
        V('Do you think remote work will permanently reduce demand for office space?', 'Как вы думаете, удалённая работа навсегда снизит спрос на офисные площади?', 'Қашықтан жұмыс кеңсе алаңдарына деген сұранысты мәңгі азайтады деп ойлайсыз ба?'),
        V('Should cities invest more in green and open public spaces?', 'Должны ли города больше инвестировать в зелёные и открытые общественные пространства?', 'Қалалар жасыл және ашық қоғамдық кеңістіктерге көбірек инвестиция салуы керек пе?'),
        V('Do you think mixed-use neighborhoods are better than single-purpose zoning?', 'Как вы думаете, многофункциональные районы лучше, чем зонирование по единственному назначению?', 'Аралас пайдаланылатын аудандар бір мақсатты аймақтарға бөлуден жақсы деп ойлайсыз ба?'),
        V('Has your own city changed noticeably in recent years?', 'Ваш город заметно изменился в последние годы?', 'Қалаңыз соңғы жылдары айтарлықтай өзгерді ме?'),
        V('Do you think ventilation and air quality should be a bigger focus in building design?', 'Как вы думаете, вентиляция и качество воздуха должны быть в большем фокусе в проектировании зданий?', 'Ғимарат жобалауда желдету мен ауа сапасына көбірек назар аударылуы керек пе деп ойлайсыз ба?'),
        V('Do you think smaller cities will grow as people move away from big cities?', 'Как вы думаете, небольшие города будут расти по мере того, как люди уезжают из больших городов?', 'Адамдар үлкен қалалардан көшкен сайын кішкентай қалалар өседі деп ойлайсыз ба?'),
        V('Should city planning involve more input from residents directly?', 'Должно ли городское планирование больше учитывать мнение жителей напрямую?', 'Қала жоспарлауда тұрғындардың пікірі тікелей көбірек ескерілуі керек пе?'),
        V('What change would make your city more resilient to future disruptions?', 'Какое изменение сделало бы ваш город более устойчивым к будущим сбоям?', 'Қандай өзгеріс қалаңызды болашақ бұзылуларға төзімдірек ете алады?'),
